fts5.h1_f:
CREATE VIRTUAL TABLE meldinger_fts USING fts5(
  innhold, -- tokenisert kolonne
  room_id UNINDEXED,
  tokenize = 'unicode61 remove_diacritics 2'
);
spørring: SELECT rowid FROM messages_fts WHERE innhold MATCH 'foo'

